package com.delivery.platform.catalog.variant.api;
import com.delivery.platform.catalog.common.CatalogSupport;import com.delivery.platform.common.ApiException;import com.delivery.platform.identity.security.IdentityPrincipal;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.http.HttpStatus;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import java.math.*;import java.util.*;
@RestController public class VariantController {private final JdbcClient db;private final CatalogSupport support;public VariantController(JdbcClient d,CatalogSupport s){db=d;support=s;}public record Variant(UUID id,UUID productId,String sku,String name,BigDecimal price,BigDecimal compareAtPrice,BigDecimal stockQuantity,boolean available,boolean active,int sortOrder){}public record Save(String sku,@NotBlank String name,@NotNull @DecimalMin("0")BigDecimal price,@DecimalMin("0")BigDecimal compareAtPrice,@DecimalMin("0")BigDecimal stockQuantity,boolean available,Integer sortOrder){}
 @GetMapping("/api/v1/products/{productId}/variants") @PreAuthorize("hasAuthority('CATALOG_PRODUCTS_VIEW')") List<Variant> list(@AuthenticationPrincipal IdentityPrincipal p,@PathVariable UUID productId){support.product(p,productId);return db.sql("select * from product_variants where tenant_id=:t and product_id=:p and active order by sort_order,name").param("t",p.tenantId()).param("p",productId).query((r,n)->map(r)).list();}
 @PostMapping("/api/v1/products/{productId}/variants") @Transactional @PreAuthorize("hasAuthority('CATALOG_PRODUCTS_UPDATE')") Variant create(@AuthenticationPrincipal IdentityPrincipal p,@PathVariable UUID productId,@Valid @RequestBody Save q){support.product(p,productId);if(q.compareAtPrice()!=null&&q.compareAtPrice().compareTo(q.price())<0)throw new ApiException(HttpStatus.BAD_REQUEST,"INVALID_VARIANT_PRICE","El precio comparativo debe ser mayor o igual al precio");UUID id=UUID.randomUUID();db.sql("insert into product_variants(id,tenant_id,product_id,sku,name,price,compare_at_price,stock_quantity,available,sort_order) values(:i,:t,:p,:s,:n,:r,:c,:q,:a,:o)").param("i",id).param("t",p.tenantId()).param("p",productId).param("s",q.sku()).param("n",q.name()).param("r",q.price()).param("c",q.compareAtPrice()).param("q",q.stockQuantity()).param("a",q.available()).param("o",q.sortOrder()==null?0:q.sortOrder()).update();support.audit(p,"VARIANT_CREATED","VARIANT",id);return one(p,id);}
 @GetMapping("/api/v1/variants/{id}") @PreAuthorize("hasAuthority('CATALOG_PRODUCTS_VIEW')") Variant one(@AuthenticationPrincipal IdentityPrincipal p,@PathVariable UUID id){return db.sql("select * from product_variants where id=:i and tenant_id=:t").param("i",id).param("t",p.tenantId()).query((r,n)->map(r)).optional().orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"VARIANT_NOT_FOUND","Variante no encontrada"));}
 @DeleteMapping("/api/v1/variants/{id}") @Transactional @PreAuthorize("hasAuthority('CATALOG_PRODUCTS_UPDATE')") void delete(@AuthenticationPrincipal IdentityPrincipal p,@PathVariable UUID id){one(p,id);db.sql("update product_variants set active=false,available=false,updated_at=now() where id=:i").param("i",id).update();support.audit(p,"VARIANT_DELETED","VARIANT",id);}private Variant map(java.sql.ResultSet r)throws java.sql.SQLException{return new Variant(r.getObject("id",UUID.class),r.getObject("product_id",UUID.class),r.getString("sku"),r.getString("name"),r.getBigDecimal("price"),r.getBigDecimal("compare_at_price"),r.getBigDecimal("stock_quantity"),r.getBoolean("available"),r.getBoolean("active"),r.getInt("sort_order"));}}
